import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_3/projects/gen-depth-fingerprint/registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

# Find all experiments with status PLANNED or PENDING
planned_experiments = []
for exp_id, exp_data in data.get('experiments', {}).items():
    if exp_data.get('status') in ['PLANNED', 'PENDING']:
        planned_experiments.append((exp_id, exp_data.get('status')))

if planned_experiments:
    print(f"Found {len(planned_experiments)} planned/pending experiments:")
    for exp_id, status in planned_experiments:
        print(f"  - {exp_id}: {status}")
else:
    print("No experiments with status PLANNED or PENDING found")

# Show all statuses present in registry
print("\nExperiment status summary:")
status_counts = {}
for exp_id, exp_data in data.get('experiments', {}).items():
    status = exp_data.get('status', 'UNKNOWN')
    status_counts[status] = status_counts.get(status, 0) + 1

for status, count in sorted(status_counts.items()):
    print(f"  {status}: {count}")

# List the total number of experiments
print(f"\nTotal experiments in registry: {len(data.get('experiments', {}))}")
EOF
